try {
  const results = $input.first().json.results || [];
  return results.map(job => ({
    json: {
      source_id: `adzuna_gb_${job.id}`,
      source: 'adzuna', title: job.title || '',
      company: (job.company && job.company.display_name) || '',
      location: (job.location && job.location.display_name) || 'Remote',
      country: 'global',
      salary_min: job.salary_min || null, salary_max: job.salary_max || null,
      currency: job.salary_currency || 'GBP',
      description: job.description || '',
      application_url: job.redirect_url || '',
      application_type: 'external_link',
      posted_at: job.created || new Date().toISOString(),
      discovered_at: new Date().toISOString()
    }
  }));
} catch(e) { return [{ json: { _error: e.message, _source: 'adzuna_gb' } }]; }

