try {
  return $input.map(item => ({
    json: {
      source_id: `rss_${item.json.guid || item.json.link || Math.random().toString(36).slice(2)}`,
      source: 'rss', title: item.json.title || '',
      company: item.json.author || item.json['dc:creator'] || '',
      location: 'Remote', country: 'global',
      salary_min: null, salary_max: null, currency: null,
      description: item.json.description || item.json.content || '',
      application_url: item.json.link || '',
      application_type: 'external_link',
      posted_at: item.json.pubDate || item.json.isoDate || new Date().toISOString(),
      discovered_at: new Date().toISOString()
    }
  }));
} catch(e) { return [{ json: { _error: e.message, _source: 'rss' } }]; }

// Safely collects items from ALL upstream branches into one stream
const allItems = [];
for (const input of $input.all()) {
  if (input && input.length > 0) {
    for (const item of input) {
      if (item.json && !item.json._error) {
        allItems.push(item);
      }
    }
  }
}
return allItems;

try {
  const seen = new Set();
  const remoteKeywords = ['remote', 'anywhere', 'work from home', 'hybrid'];
  return $input.filter(item => {
    const job = item.json;
    if (job._error) return false;
    const loc = (job.location || '').toLowerCase();
    const desc = (job.description || '').toLowerCase();
    const isRemote = remoteKeywords.some(kw => loc.includes(kw) || desc.includes(kw));
    if (!isRemote) return false;
    const key = `${(job.company || '').toLowerCase().trim()}|${(job.title || '').toLowerCase().trim()}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
} catch(e) { return [{ json: { _error: e.message } }]; }
